#!/bin/sh
set -eu
# Keep Apache stopped until the initial site owner exists.
docker-ensure-installed.sh
attempt=0
until php -r 'mysqli_report(MYSQLI_REPORT_OFF); $db = @new mysqli(getenv("WORDPRESS_DB_HOST"), getenv("WORDPRESS_DB_USER"), getenv("WORDPRESS_DB_PASSWORD"), getenv("WORDPRESS_DB_NAME")); exit($db->connect_errno ? 1 : 0);'; do
  attempt=$((attempt + 1))
  if [ "$attempt" -ge 60 ]; then
    echo 'WordPress could not connect to its database during setup.' >&2
    exit 1
  fi
  sleep 2
done
su -s /bin/sh www-data -c 'php' <<'PHP'
<?php
// Use the installation API shipped in this official image; no extra CLI download.
define('WP_INSTALLING', true);
$url = getenv('OPENSHIP_PUBLIC_URL');
$parts = parse_url($url);
if (!$parts || empty($parts['host']) || !in_array($parts['scheme'] ?? '', ['http', 'https'], true)) {
    fwrite(STDERR, "WordPress needs a valid website URL before setup.\n");
    exit(1);
}
$_SERVER['HTTP_HOST'] = $parts['host'] . (isset($parts['port']) ? ':' . $parts['port'] : '');
$_SERVER['REQUEST_URI'] = '/';
$_SERVER['REQUEST_METHOD'] = 'GET';
require '/var/www/html/wp-load.php';
require '/var/www/html/wp-admin/includes/upgrade.php';
if (!is_blog_installed()) {
    $username = getenv('OPENSHIP_ADMIN_USER');
    $password = getenv('OPENSHIP_ADMIN_PASSWORD');
    $email = getenv('OPENSHIP_ADMIN_EMAIL');
    $title = getenv('OPENSHIP_SITE_TITLE');
    if (!validate_username($username) || $password === false || $password === '' || !is_email($email) || $title === false || $title === '') {
        fwrite(STDERR, "WordPress needs valid initial owner settings before setup.\n");
        exit(1);
    }
    // Match the previous bootstrap's --skip-email behavior, only in this process.
    add_filter('pre_wp_mail', '__return_false');
    $installed = wp_install($title, $username, $email, true, '', $password);
    if (empty($installed['user_id']) || !user_can($installed['user_id'], 'manage_options') || !is_blog_installed()) {
        fwrite(STDERR, "WordPress initialization did not complete; the website was not started.\n");
        exit(1);
    }
    echo "WordPress site and owner initialized.\n";
}
PHP
exec docker-entrypoint.sh "$@"

const { existsSync, writeFileSync } = require('node:fs');
for (const [file, content] of Object.entries({ 'settings.yaml': 'title: My services\n', 'services.yaml': '[]\n', 'bookmarks.yaml': '[]\n', 'widgets.yaml': '[]\n', 'docker.yaml': '{}\n', 'kubernetes.yaml': '{}\n' })) {
  const path = '/app/config/' + file;
  if (!existsSync(path)) writeFileSync(path, content, { mode: 0o600 });
}
require('/app/server.js');

{
  auto_https off
  admin off
}
:8080 {
  basic_auth {
    {$OPENSHIP_ADMIN_USER} {$OPENSHIP_PASSWORD_HASH}
  }
  reverse_proxy homepage:3000 {
    header_up Host homepage:3000
  }
}

const { writeFileSync } = require('node:fs');
const { spawn } = require('node:child_process');
const { networkInterfaces } = require('node:os');
const pause = ms => new Promise(resolve => setTimeout(resolve, ms));
let child;
let stopping = false;
for (const signal of ['SIGTERM', 'SIGINT']) process.on(signal, () => { if (stopping) return; stopping = true; void stop().then(() => process.exit(143), () => process.exit(1)); });
function start(host, setup) {
  if (stopping) throw new Error('Immich setup was interrupted.');
  child = spawn('start.sh', [], { env: { ...process.env, IMMICH_HOST: host, IMMICH_ALLOW_SETUP: setup }, stdio: 'inherit', detached: true });
}
async function stop() {
  if (!child) return;
  const processGroup = child.pid;
  const alive = () => { try { process.kill(-processGroup, 0); return true; } catch (error) { if (error.code === 'ESRCH') return false; throw error; } };
  if (!alive()) return;
  process.kill(-processGroup, 'SIGTERM');
  for (let attempt = 0; attempt < 300 && alive(); attempt++) await pause(100);
  if (alive()) process.kill(-processGroup, 'SIGKILL');
}
async function config(host = '127.0.0.1') {
  const response = await fetch('http://' + host + ':2283/api/server/config', { signal: AbortSignal.timeout(5000) });
  if (!response.ok) throw new Error('Immich did not return its setup status.');
  const value = await response.json();
  if (typeof value.isInitialized !== 'boolean') throw new Error('Immich returned an invalid setup status.');
  return value;
}
(async () => {
  start('127.0.0.1', 'true');
  let initial;
  for (let attempt = 0; attempt < 240; attempt++) {
    if (child.exitCode !== null) throw new Error('Immich exited during private setup.');
    try { initial = await config(); break; } catch (error) { if (!(error instanceof TypeError) && error.name !== 'TimeoutError') throw error; }
    await pause(2000);
  }
  if (!initial) throw new Error('Immich private setup timed out.');
  if (!initial.isInitialized) {
    const response = await fetch('http://127.0.0.1:2283/api/auth/admin-sign-up', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: process.env.OPENSHIP_ADMIN_EMAIL, name: process.env.OPENSHIP_ADMIN_NAME, password: process.env.OPENSHIP_ADMIN_PASSWORD }), signal: AbortSignal.timeout(30000) });
    if (!response.ok || (await response.json()).isAdmin !== true) throw new Error('Immich initial owner setup was rejected.');
    if (!(await config()).isInitialized) throw new Error('Immich owner setup did not persist.');
  }
  await stop();
  start('0.0.0.0', 'false');
  // Probe the container's non-loopback address: an old private worker cannot
  // satisfy public readiness while the new API is still starting.
  const address = Object.values(networkInterfaces()).flat().find(value => value && value.family === 'IPv4' && !value.internal)?.address;
  if (!address) throw new Error('Immich has no private network address for its public listener.');
  let publicReady = false;
  for (let attempt = 0; attempt < 180; attempt++) {
    if (child.exitCode !== null) throw new Error('Immich public server exited during startup.');
    try { if ((await config(address)).isInitialized) { publicReady = true; break; } } catch (error) { if (!(error instanceof TypeError) && error.name !== 'TimeoutError') throw error; }
    await pause(2000);
  }
  if (!publicReady) throw new Error('Immich public listener did not become ready.');
  writeFileSync('/tmp/openship-ready', 'ready', { mode: 0o600 });
  child.once('exit', code => { if (!stopping) process.exit(code ?? 1); });
})().catch(async error => { if (stopping) return; if (typeof error.message === "string" && error.message.startsWith("Immich ")) console.error(error.message); console.error('Immich could not complete private owner setup; the public service was not started.'); if (child?.exitCode === null) await stop(); process.exit(1); });

const { spawn } = require('node:child_process');
const { writeFileSync } = require('node:fs');
const { Client } = require('/wiki/node_modules/pg');
const pause = ms => new Promise(resolve => setTimeout(resolve, ms));
let child;
let stopping = false;
for (const signal of ['SIGTERM', 'SIGINT']) process.on(signal, () => { if (stopping) return; stopping = true; void stop().then(() => process.exit(143), () => process.exit(1)); });
function start(bindIP) {
  if (stopping) throw new Error('Wiki.js setup was interrupted.');
  const config = { port: 3000, bindIP, db: { type: 'postgres', host: process.env.DB_HOST, port: 5432, user: process.env.DB_USER, pass: process.env.DB_PASS, db: process.env.DB_NAME, ssl: false }, dataPath: '/wiki/data', ssl: { enabled: false }, logLevel: 'info' };
  writeFileSync('/tmp/openship-wiki-config.json', JSON.stringify(config), { mode: 0o600 });
  child = spawn(process.execPath, ['--no-deprecation', 'server'], { cwd: '/wiki', env: { ...process.env, CONFIG_FILE: '/tmp/openship-wiki-config.json' }, stdio: 'inherit' });
}
async function stop() {
  if (!child || child.exitCode !== null) return;
  const closed = new Promise(resolve => child.once('exit', resolve));
  child.kill('SIGTERM');
  const timeout = setTimeout(() => child.kill('SIGKILL'), 30000);
  await closed;
  clearTimeout(timeout);
}
(async () => {
  start('127.0.0.1');
  const db = new Client({ host: process.env.DB_HOST, user: process.env.DB_USER, password: process.env.DB_PASS, database: process.env.DB_NAME });
  await db.connect();
  let ready = false;
  for (let attempt = 0; attempt < 180; attempt++) {
    if (child.exitCode !== null) throw new Error('Wiki.js exited during private setup.');
    const tables = await db.query("SELECT to_regclass('public.settings') IS NOT NULL AND to_regclass('public.users') IS NOT NULL AS ready");
    if (tables.rows[0].ready) {
      const settings = await db.query('SELECT COUNT(*)::int AS count FROM settings');
      const owner = await db.query('SELECT id FROM users WHERE id = 1');
      if (settings.rows[0].count > 0 && owner.rows.length) { ready = true; break; }
      if (settings.rows[0].count > 0 || owner.rows.length) throw new Error('Wiki.js has incomplete existing setup. Restore or repair it before publishing.');
      try {
        const response = await fetch('http://127.0.0.1:3000/finalize', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ adminEmail: process.env.OPENSHIP_ADMIN_EMAIL, adminPassword: process.env.OPENSHIP_ADMIN_PASSWORD, siteUrl: process.env.OPENSHIP_PUBLIC_URL, telemetry: false }), signal: AbortSignal.timeout(120000) });
        const result = await response.json();
        if (!response.ok || result.ok !== true) throw new Error('Wiki.js initial owner setup was rejected.');
        ready = true; break;
      } catch (error) {
        if (!(error instanceof TypeError)) throw error;
      }
    }
    await pause(2000);
  }
  if (!ready) throw new Error('Wiki.js private setup timed out.');
  const owner = await db.query('SELECT id FROM users WHERE id = 1');
  if (!owner.rows.length) throw new Error('Wiki.js owner was not created; refusing to publish.');
  await db.end();
  await stop();
  start('0.0.0.0');
  writeFileSync('/tmp/openship-ready', 'ready', { mode: 0o600 });
  child.once('exit', code => { if (!stopping) process.exit(code ?? 1); });
})().catch(async error => { if (stopping) return; if (typeof error.message === "string" && error.message.startsWith("Wiki.js ")) console.error(error.message); console.error('Wiki.js could not complete private owner setup; the public service was not started.'); if (child?.exitCode === null) await stop(); process.exit(1); });
